import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    username = (query.get("username") or [""])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT, role TEXT)"
    )
    cur.execute(
        "CREATE TABLE secrets (id INTEGER PRIMARY KEY, secret_key TEXT, secret_value TEXT)"
    )
    cur.executemany(
        "INSERT INTO users (username, role) VALUES (?, ?)",
        [("alice", "admin"), ("bob", "user"), ("charlie", "user")],
    )
    cur.execute(
        "INSERT INTO secrets (secret_key, secret_value) VALUES (?, ?)",
        ("flag", flag),
    )
    conn.commit()

    sql = "SELECT id, username, role FROM users WHERE username = '" + username + "'"
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "DB error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "No user found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
